	key := c.Param("key")
	if strings.TrimSpace(key) == "" {
		writeNotFound(c)
		return
	}
	record, err := st.ActiveRecordByKey(c.Request.Context(), key, time.Now().UTC())
	if err != nil {
		writeStorageUnavailable(c)
		return
	}
	if record == nil {
		writeNotFound(c)
		return
	}
	c.JSON(http.StatusOK, recordEnvelope{Record: toRecordResponse(record)})
}

